    "intro": "__osrt1__:{\"version\":1,\"root\":{\"type\":\"root\",\"children\":[{\"type\":\"p\",\"children\":[{\"type\":\"strong\",\"children\":[{\"type\":\"text\",\"text\":\"Important:\"}]},{\"type\":\"text\",\"text\":\" CashPath is a personal-loan request and referral service, not a car-title lender, auto lender, bank, or legal adviser. Car-title-loan availability, fees, repayment rules, repossession rights, and consumer protections vary by state and contract. This page does not state that title loans are legal or illegal in any particular state and does not promise that a personal loan will be available or lower-cost. CashPath may receive referral compensation; see the \"},{\"type\":\"a\",\"href\":\"/p/advertiser-disclosure\",\"children\":[{\"type\":\"text\",\"text\":\"Advertiser Disclosure\"}]},{\"type\":\"text\",\"text\":\".\"}]}]}}",
    "is_visible": true,
